/**
 * Animation data for data-block
 *
 * bpy.types.AnimData
 */
export interface AnimData extends R.bpy_struct {
  /** NLA Tracks (i.e. Animation Layers) */
  readonly nla_tracks: H.Own<H.Coll<R.NlaTrack> & R.NlaTracks>;
  /** Active Action for this data-block */
  get action(): H.Ptr<R.Action>;
  set action(v: R.Action | null);
  /**
   * Action to take for gaps past the Active Action's range (when evaluating with NLA) Default: 'HOLD'.
   * - `NOTHING`: Nothing (Strip has no influence past its extents)
   * - `HOLD`: Hold (Hold the first frame if no previous strips in track, and always hold last frame)
   * - `HOLD_FORWARD`: Hold Forward (Only hold last frame)
   */
  get action_extrapolation(): H.Ref<"NOTHING" | "HOLD" | "HOLD_FORWARD">;
  set action_extrapolation(v: H.In<"NOTHING" | "HOLD" | "HOLD_FORWARD">);
  /**
   * Method used for combining Active Action's result with result of NLA stack Default: 'REPLACE'.
   * - `REPLACE`: Replace (The strip values replace the accumulated results by amount specified by influence)
   * - `COMBINE`: Combine (The strip values are combined with accumulated results by appropriately using addition, multiplication, or quaternion math, based on channel type)
   * - `ADD`: Add (Weighted result of strip is added to the accumulated results)
   * - `SUBTRACT`: Subtract (Weighted result of strip is removed from the accumulated results)
   * - `MULTIPLY`: Multiply (Weighted result of strip is multiplied with the accumulated results)
   */
  get action_blend_type(): H.Ref<"REPLACE" | "COMBINE" | "ADD" | "SUBTRACT" | "MULTIPLY">;
  set action_blend_type(v: H.In<"REPLACE" | "COMBINE" | "ADD" | "SUBTRACT" | "MULTIPLY">);
  /** Amount the Active Action contributes to the result of the NLA stack Range: 0 to 1. Default: 1.0. */
  get action_influence(): H.Ref<number>;
  set action_influence(v: H.In<number>);
  /** Storage to temporarily hold the main action while in tweak mode */
  get action_tweak_storage(): H.Ptr<R.Action>;
  set action_tweak_storage(v: R.Action | null);
  /** Storage to temporarily hold the main action slot while in tweak mode Range: -2147483648 to 2147483647. Default: 0. */
  get action_slot_handle_tweak_storage(): H.Ref<number>;
  set action_slot_handle_tweak_storage(v: H.In<number>);
  /** The Drivers/Expressions for this data-block */
  readonly drivers: H.Own<H.Coll<R.FCurve> & R.AnimDataDrivers>;
  /** NLA stack is evaluated when evaluating this block Default: True. */
  get use_nla(): H.Ref<boolean>;
  set use_nla(v: H.In<boolean>);
  /** Whether to enable or disable tweak mode in NLA Default: False. */
  get use_tweak_mode(): H.Ref<boolean>;
  set use_tweak_mode(v: H.In<boolean>);
  /** Pin in Graph Editor Default: False. */
  get use_pin(): H.Ref<boolean>;
  set use_pin(v: H.In<boolean>);
  /** A number that identifies which sub-set of the Action is considered to be for this data-block Range: -2147483648 to 2147483647. Default: 0. */
  get action_slot_handle(): H.Ref<number>;
  set action_slot_handle(v: H.In<number>);
  /** The identifier of the most recently assigned action slot. The slot identifies which sub-set of the Action is considered to be for this data-block, and its identifier is used to find the right slot when assigning an Action. Default: "". */
  get last_slot_identifier(): H.Ref<string>;
  set last_slot_identifier(v: H.In<string>);
  /** The slot identifies which sub-set of the Action is considered to be for this data-block, and its name is used to find the right slot when assigning an Action */
  get action_slot(): H.Ptr<R.ActionSlot>;
  set action_slot(v: R.ActionSlot | null);
  /** The list of slots in this animation data-block */
  readonly action_suitable_slots: H.Own<H.Coll<R.ActionSlot>>;
  /**
   * Convert a time value from the local time of the tweaked strip to scene time, exactly as done by built-in key editing tools. Returns the input time unchanged if not tweaking.
   * @param frame Input time
   * @param invert Convert scene time to action time
   */
  nla_tweak_strip_time_to_scene(frame: H.In<number>, invert?: H.In<boolean>): H.Ref<number>;
  /**
   * Convert a time value from the local time of the tweaked strip to scene time, exactly as done by built-in key editing tools. Returns the input time unchanged if not tweaking.
   * @param frame Input time
   * @param invert Convert scene time to action time
   */
  nla_tweak_strip_time_to_scene(frame: H.In<number>, kw: {
    /** Convert scene time to action time */
    invert?: H.In<boolean>;
  }): H.Ref<number>;
  /**
   * Convert a time value from the local time of the tweaked strip to scene time, exactly as done by built-in key editing tools. Returns the input time unchanged if not tweaking.
   * @param frame Input time
   * @param invert Convert scene time to action time
   */
  nla_tweak_strip_time_to_scene(kw: {
    /** Input time */
    frame: H.In<number>;
    /** Convert scene time to action time */
    invert?: H.In<boolean>;
  }): H.Ref<number>;
  /**
   * Rename the property paths in the animation system, since properties are animated via string paths, it's needed to keep them valid after properties has been renamed
   * @param prefix Name prefix
   * @param old_name Old name
   * @param new_name New name
   */
  fix_paths_rename_all(prefix?: H.In<string>, old_name?: H.In<string>, new_name?: H.In<string>): H.Ref<void>;
  /**
   * Rename the property paths in the animation system, since properties are animated via string paths, it's needed to keep them valid after properties has been renamed
   * @param prefix Name prefix
   * @param old_name Old name
   * @param new_name New name
   */
  fix_paths_rename_all(kw: {
    /** Name prefix */
    prefix?: H.In<string>;
    /** Old name */
    old_name?: H.In<string>;
    /** New name */
    new_name?: H.In<string>;
  }): H.Ref<void>;
}

